/**
 * @name Path traversal in file operations
 * @description User-controlled file paths without validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/click-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to functions that might receive user input
    exists(DataFlow::ParameterNode param |
      source = param and
      (
        param.getParameter().getName() in ["filename", "path", "file", "name", "dir", "directory"]
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"

/**
 * @name Open redirect via webbrowser
 * @description Opening URLs from user input without validation can lead to open redirect vulnerabilities
 * @kind path-problem
 * @problem.severity warning
 * @id py/click-open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from command-line arguments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("click").getMember("prompt").getACall() or
      call = API::moduleImport("click").getMember("get_text_stream").getACall()
    |
      source = call
    )
    or
    // Function parameters that could be user-controlled
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("webbrowser").getMember(["open", "open_new", "open_new_tab"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential open redirect from $@.", source.getNode(), "user input"

/**
 * @name Code injection via eval/exec/compile
 * @description Using eval, exec, or compile with user input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/click-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["read", "readline", "readlines"] and
      source = call
    )
    or
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
